import { SchemaValidator } from 'codelijst-rie-iepr-poc-json-schema/browser';
const string = { type: 'string' };
const strings = { type: 'array', items: string };
const reference = {
    type: 'object', additionalProperties: false, required: ['id', 'label', 'types'],
    properties: {
        id: { type: 'string', minLength: 1 }, label: { type: 'string', minLength: 1 },
        types: { type: 'array', minItems: 1, items: string }, parents: strings, year: { type: 'integer' },
    },
};
const referencesSchema = { type: 'array', items: reference };
const contextSchema = {
    type: 'object', additionalProperties: false,
    properties: { year: { type: 'integer' }, ids: strings },
};
const row = {
    type: 'object', additionalProperties: false, required: ['recordId', 'reference', 'instancePath'],
    properties: {
        recordId: string, parentId: string, reference: string, parentReference: string,
        instancePath: string, parentInstancePath: string,
    },
};
const choice = {
    type: 'object', additionalProperties: false, required: ['value', 'display'],
    properties: { value: { anyOf: [{ type: 'string' }, { type: 'number' }, { type: 'boolean' }] }, display: string },
};
const metadataSchema = {
    type: 'object', additionalProperties: false,
    required: ['version', 'schemaId', 'schemaSha256', 'sourceSha256', 'planSha256', 'lookups', 'rows', 'references', 'jsonMapping'],
    properties: {
        version: { const: 2 }, schemaId: string,
        jsonMapping: {
            type: 'object', additionalProperties: false, patternProperties: { '^.*$': {
                    type: 'object', additionalProperties: false, required: ['pathTemplate', 'columns'],
                    properties: {
                        pathTemplate: string, parentPathTemplate: string, parentIdentifierPath: string,
                        columns: { type: 'object', additionalProperties: false, patternProperties: { '^.*$': string } },
                    }
                },
            },
        },
        schemaSha256: { type: 'string', pattern: '^[a-f0-9]{64}$' },
        sourceSha256: { type: 'string', pattern: '^[a-f0-9]{64}$' },
        planSha256: { type: 'string', pattern: '^[a-f0-9]{64}$' },
        lookups: { type: 'object', additionalProperties: false, patternProperties: { '^c_[0-9a-f]{24}$': { type: 'array', items: choice } } },
        rows: { type: 'object', additionalProperties: false, patternProperties: { '^[0-9a-f-]{36}$': row } },
        references: referencesSchema,
        referenceContext: contextSchema,
        layout: { const: 'business-v1' },
        businessRows: {
            type: 'object', additionalProperties: false,
            patternProperties: {
                '^[0-9a-f-]{36}$': {
                    type: 'object', additionalProperties: false, required: ['values', 'containers'],
                    properties: {
                        values: { type: 'object', additionalProperties: { anyOf: [{ type: 'string' }, { type: 'number' }, { type: 'boolean' }] } },
                        containers: {
                            type: 'array', items: {
                                type: 'object', additionalProperties: false, required: ['path', 'kind', 'required'],
                                properties: { path: strings, kind: { enum: ['object', 'array'] }, required: { type: 'boolean' } },
                            },
                        },
                    },
                },
            },
        },
    },
};
function assertValid(schema, value, description) {
    const result = new SchemaValidator().validateInstance(schema, value);
    if (!result.valid)
        throw new Error(`${description}: ${result.errors.map(error => `${error.instancePath} ${error.message}`).join('; ')}`);
}
export function referenceContext(value) {
    assertValid(contextSchema, value, 'Invalid reference context');
    return value;
}
export function referenceData(value) {
    assertValid(referencesSchema, value, 'Invalid reference data');
    const references = value;
    if (new Set(references.map(reference => reference.id)).size !== references.length)
        throw new Error('Duplicate reference-data identities.');
    return references;
}
export function workbookMetadata(value) {
    assertValid(metadataSchema, value, 'Missing or incompatible workbook metadata');
    const metadata = value;
    referenceData(metadata.references);
    return metadata;
}
